<?php $pageTitle='Coupons';$subtitle='Create and control the offers customers see during checkout.';$active='Coupons';require __DIR__.'/_layout.php';$rows=db()->query('SELECT * FROM coupons ORDER BY id DESC')->fetchAll();?><div class="card"><div class="section-head"><h2>Coupon management</h2><button class="btn primary" id="newCoupon">Add Coupon</button></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Offer</th><th>Minimum</th><th>Dates</th><th>Usage</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=ae($r['code'])?></strong></td><td><?=ae($r['title'])?><br><small><?=ae($r['discount_type'])?> <?=number_format((float)$r['discount_value'],2)?><?php if($r['max_discount']):?> · Max ₹<?=number_format((float)$r['max_discount'],2)?><?php endif;?></small></td><td>₹<?=number_format((float)$r['min_order_amount'],2)?></td><td><?=ae($r['starts_at']??'Now')?> → <?=ae($r['expires_at']??'No expiry')?></td><td><?=number_format((int)$r['usage_count'])?><?= $r['usage_limit']!==null?' / '.number_format((int)$r['usage_limit']):''?></td><td><span class="pill <?=((int)$r['active']?'green':'red')?>"><?=((int)$r['active']?'Active':'Disabled')?></span></td><td><button class="btn" onclick='editCoupon(<?=json_encode($r,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)'>Edit</button></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty">No coupons.</td></tr><?php endif;?></tbody></table></div></div><div class="modal" id="couponModal"><div class="modal-box" style="max-width:720px"><div class="modal-head"><h2>Coupon</h2><button class="close" onclick="couponModal.classList.remove('open')">×</button></div><form id="couponForm"><input type="hidden" name="id"><div class="form-grid"><div class="field"><label>Code</label><input class="input" name="code" required></div><div class="field"><label>Title</label><input class="input" name="title"></div><div class="field full"><label>Description</label><input class="input" name="description"></div><div class="field"><label>Type</label><select class="select" name="discount_type"><option value="percent">Percent</option><option value="fixed">Fixed</option></select></div><div class="field"><label>Discount Value</label><input class="input" name="discount_value" type="number" step="0.01"></div><div class="field"><label>Max Discount</label><input class="input" name="max_discount" type="number" step="0.01"></div><div class="field"><label>Minimum Order</label><input class="input" name="min_order_amount" type="number" step="0.01"></div><div class="field"><label>Starts At</label><input class="input" name="starts_at" type="datetime-local"></div><div class="field"><label>Expires At</label><input class="input" name="expires_at" type="datetime-local"></div><div class="field"><label>Usage Limit</label><input class="input" name="usage_limit" type="number"></div><div class="field"><label>Per User Limit</label><input class="input" name="per_user_limit" type="number" value="1"></div><div class="field"><label>Active</label><select class="select" name="active"><option value="1">Active</option><option value="0">Disabled</option></select></div></div><button class="btn primary" style="margin-top:15px">Save Coupon</button></form></div></div><script>const couponModal=document.querySelector('#couponModal');document.querySelector('#newCoupon').onclick=()=>{document.querySelector('#couponForm').reset();document.querySelector('[name=id]').value='';couponModal.classList.add('open')};function editCoupon(c){const f=document.querySelector('#couponForm');for(const k of ['id','code','title','description','discount_type','discount_value','max_discount','min_order_amount','starts_at','expires_at','usage_limit','per_user_limit','active'])if(f.elements[k])f.elements[k].value=c[k]??'';couponModal.classList.add('open')}document.querySelector('#couponForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('action','save-coupon');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),500)})</script><?php require __DIR__.'/_foot.php';?>
